const fs = require('fs');
// 문의함 — 카카오 채널 관리자 + 네이버 톡톡 파트너센터를 한 창에서, 자기 아이디로 로그인해서 쓰는 메신저
const { app, BrowserWindow, Tray, Menu, ipcMain, dialog, session, nativeImage, shell } = require('electron');
const path = require('path');

// 카카오/네이버가 "지원하지 않는 브라우저"라고 막지 않도록 일반 크롬처럼 보이게 합니다.
const CHROME_UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36';
app.userAgentFallback = CHROME_UA;

if (!app.requestSingleInstanceLock()) { app.quit(); }

let win = null, tray = null, quitting = false;
const ASSETS = app.getAppPath();                 // 아이콘 등은 설치된 프로그램 안에서
const ICON = path.join(ASSETS, 'build', 'icon.png');

function createWindow() {
  const { screen } = require('electron');
  const boundsFile = path.join(app.getPath('userData'), 'window.json');
  let saved = null; try { saved = JSON.parse(fs.readFileSync(boundsFile, 'utf8')); } catch (_) {}
  const wa = screen.getPrimaryDisplay().workArea;
  let b = { width: Math.min(1360, Math.round(wa.width * 0.92)), height: Math.min(900, Math.round(wa.height * 0.92)) };
  if (saved && screen.getAllDisplays().some((d) => { const w = d.workArea; return saved.x >= w.x - 50 && saved.y >= w.y - 50 && saved.x < w.x + w.width - 100 && saved.y < w.y + w.height - 100; })) b = saved;
  win = new BrowserWindow({
    ...b, minWidth: 760, minHeight: 520,
    title: 'KD통합메신저', icon: ICON, backgroundColor: '#1D2B4A',
    webPreferences: {
      preload: path.join(__dirname, 'preload-host.js'),
      contextIsolation: true, webviewTag: true,
    },
  });
  win.removeMenu();
  win.loadFile(path.join(__dirname, 'index.html'));
  // X를 눌러도 꺼지지 않고 트레이로 숨어서 계속 알림을 받습니다.
  // X를 눌러도 꺼지지 않고 작업표시줄에 남아서, 새 문의가 오면 아이콘에 불이 들어옵니다.
  win.on('close', (e) => { if (!quitting) { e.preventDefault(); win.minimize(); } });
  win.on('focus', () => win.flashFrame(false));
  let bt = null;
  const keepBounds = () => { clearTimeout(bt); bt = setTimeout(() => { try { if (!win.isMinimized() && !win.isMaximized()) fs.writeFileSync(boundsFile, JSON.stringify(win.getBounds())); } catch (_) {} }, 500); };
  win.on('resize', keepBounds); win.on('move', keepBounds);
  win.on('blur', () => { if (pendingTotal > 0) win.flashFrame(true); });
}

function setupSessions() {
  for (const name of ['persist:kakao', 'persist:naver']) {
    const s = session.fromPartition(name);
    s.setUserAgent(CHROME_UA);
    s.setPermissionRequestHandler((wc, perm, cb) => cb(['notifications', 'media', 'clipboard-read', 'clipboard-sanitized-write', 'fullscreen'].includes(perm)));
    s.setPermissionCheckHandler((wc, perm) => perm === 'notifications' || perm === 'media');
  }
}

app.on('web-contents-created', (_, contents) => {
  // 카카오/네이버 화면 안의 작은 페이지(iframe)에서도 새 메시지 감지가 돌도록
  contents.on('will-attach-webview', (_e, webPreferences) => { webPreferences.nodeIntegrationInSubFrames = true; webPreferences.backgroundThrottling = false; });
  if (contents.getType() === 'webview') {
    // 로그인 팝업 등은 같은 로그인 정보로 새 창에서 열기, 그 외 외부 링크는 기본 브라우저로
    contents.setWindowOpenHandler(({ url }) => {
      if (/kakao\.com|naver\.com|naver\.net|daum\.net/.test(url)) {
        return { action: 'allow', overrideBrowserWindowOptions: { width: 520, height: 760, icon: ICON, autoHideMenuBar: true } };
      }
      shell.openExternal(url); return { action: 'deny' };
    });
    // 대화창 같은 새 창은 문의함 창이 있는 모니터, 문의함 창 가운데에 열기 (크기는 그대로)
    contents.on('did-create-window', (child) => {
      centerOnMain(child);
      // 대화창은 항상 원래 크기(100%)로. 메인 화면을 축소해도 대화창 글씨는 안 작아지게
      const keep = () => { try { child.webContents.setZoomFactor(1); } catch (_) {} };
      child.webContents.on('dom-ready', keep);
      child.webContents.on('did-finish-load', keep);
      child.webContents.on('did-navigate-in-page', keep);
      openChildren++; sendChildren();
      child.on('closed', () => { openChildren = Math.max(0, openChildren - 1); sendChildren(); });
    });
  }
});

let openChildren = 0;
function sendChildren() { try { if (win && !win.isDestroyed()) win.webContents.send('children', openChildren); } catch (_) {} }
function centerOnMain(child) {
  try {
    const { screen } = require('electron');
    if (!win || win.isDestroyed() || !child || child.isDestroyed()) return;
    const base = (win.isMinimized() || !win.isVisible()) ? win.getNormalBounds() : win.getBounds();
    const cb = child.getBounds();
    const wa = screen.getDisplayMatching(base).workArea;            // 문의함이 있는 모니터
    let x = Math.round(base.x + (base.width - cb.width) / 2);
    let y = Math.round(base.y + (base.height - cb.height) / 2);
    x = Math.min(Math.max(x, wa.x), wa.x + wa.width - cb.width);    // 화면 밖으로 안 나가게
    y = Math.min(Math.max(y, wa.y), wa.y + wa.height - cb.height);
    child.setBounds({ x, y, width: cb.width, height: cb.height });
  } catch (_) {}
}

function createTray() {
  tray = new Tray(nativeImage.createFromPath(path.join(ASSETS, 'tray.png')));
  tray.setToolTip('KD통합메신저');
  tray.setContextMenu(Menu.buildFromTemplate([
    { label: 'KD통합메신저 열기', click: showWin },
    { label: `버전 ${global.MH_VERSION || ''}`, enabled: false },
    { label: '컴퓨터 켜면 자동 실행', type: 'checkbox', checked: app.getLoginItemSettings().openAtLogin,
      click: (i) => app.setLoginItemSettings({ openAtLogin: i.checked }) },
    { type: 'separator' },
    { label: '완전히 종료', click: () => { quitting = true; app.quit(); } },
  ]));
  tray.on('click', showWin);
}
function showWin() { if (!win) return; if (win.isMinimized()) win.restore(); win.show(); win.focus(); }

// ── 카카오처럼 오른쪽 아래에서 올라오는 알림창 (윈도우 알림 설정과 상관없이 무조건 뜸)
const { screen } = require('electron');
const POP_W = 370, POP_H = 96, MAX_POPS = 5;
let pops = [], popSeq = 0;
function layoutPops() {
  const wa = screen.getPrimaryDisplay().workArea;
  pops.forEach((p, i) => {
    if (p.win.isDestroyed()) return;
    p.win.setBounds({ x: wa.x + wa.width - POP_W - 12, y: wa.y + wa.height - (i + 1) * (POP_H + 8) - 4, width: POP_W, height: POP_H });
  });
}
function closePop(pid) {
  const p = pops.find((x) => x.pid === pid); if (!p) return;
  clearTimeout(p.timer); if (!p.win.isDestroyed()) p.win.close();
  pops = pops.filter((x) => x !== p); layoutPops();
}
function showPopup(d) {
  // 같은 대화방 알림은 새 걸로 교체
  pops.filter((p) => p.d.tabId === d.tabId && p.d.title === d.title && p.d.warn === d.warn).forEach((p) => closePop(p.pid));
  while (pops.length >= MAX_POPS) closePop(pops[pops.length - 1].pid);
  const pid = ++popSeq;
  const w = new BrowserWindow({
    width: POP_W, height: POP_H, frame: false, transparent: false, backgroundColor: '#FFFFFF', resizable: false, movable: false,
    skipTaskbar: true, alwaysOnTop: true, focusable: false, show: false, hasShadow: false,
    webPreferences: { nodeIntegration: true, contextIsolation: false },
  });
  w.setAlwaysOnTop(true, 'screen-saver');
  w.loadFile(path.join(__dirname, 'popup.html'), { hash: encodeURIComponent(JSON.stringify({ ...d, pid })) });
  w.once('ready-to-show', () => w.showInactive());
  const p = { pid, win: w, d, timer: null };
  if (d.autoClose > 0) p.timer = setTimeout(() => closePop(pid), d.autoClose * 1000);
  pops.unshift(p); layoutPops();
}
ipcMain.on('popup-click', (_, pid) => {
  const p = pops.find((x) => x.pid === pid); if (!p) return;
  showWin(); win.webContents.send('focus-service', { tabId: p.d.tabId, notifId: p.d.notifId, chatName: p.d.chatName });
  pops.filter((x) => x.d.tabId === p.d.tabId).forEach((x) => closePop(x.pid));
});
ipcMain.on('popup-close', (_, pid) => closePop(pid));
ipcMain.on('popups-clear', (_, tabId) => pops.filter((x) => !tabId || x.d.tabId === tabId).forEach((x) => closePop(x.pid)));

ipcMain.on('alert', (_, d) => {
  if (process.env.MH_DEV) console.log('ALERT:', d.title, '/', d.body);
  showPopup(d);
  if (win && !win.isFocused()) win.flashFrame(true);
});
let pendingTotal = 0;
ipcMain.on('badge', (_, total, img) => {
  pendingTotal = total;
  if (process.platform === 'win32' && win) {
    // 작업표시줄 아이콘 위에 빨간 숫자 + 주황색 불
    win.setOverlayIcon(total && img ? nativeImage.createFromDataURL(img) : null, total ? `확인 안 한 문의 ${total}` : '');
    if (total > 0 && !win.isFocused()) win.flashFrame(true);
    if (total === 0) win.flashFrame(false);
  } else { app.setBadgeCount(total); }
  tray && tray.setToolTip(total ? `문의함 · 확인 안 한 문의 있음` : '문의함');
});
ipcMain.handle('guest-preload', () => 'file://' + path.join(__dirname, 'preload-guest.js'));
ipcMain.handle('autostart', (_, on) => { if (typeof on === 'boolean') app.setLoginItemSettings({ openAtLogin: on }); return app.getLoginItemSettings().openAtLogin; });

app.on('second-instance', showWin);
app.whenReady().then(() => {
  if (process.platform === 'win32') app.setAppUserModelId('com.munuiham.app');
  setupSessions(); createWindow(); createTray();
  // 처음 설치 시 자동 실행 켜기
  // 설치 위치가 바뀌었어도(설치 파일 버전) '컴퓨터 켜면 자동 실행'이 지금 프로그램을 가리키게
  try { if (app.getLoginItemSettings().openAtLogin && !process.env.MH_DEV) app.setLoginItemSettings({ openAtLogin: true }); } catch (_) {}
  const flag = path.join(app.getPath('userData'), 'first-run-done');
  if (!require('fs').existsSync(flag)) {
    if (!process.env.MH_DEV) app.setLoginItemSettings({ openAtLogin: true });
    require('fs').writeFileSync(flag, '1');
  }
});
// 로그인 정보 지키기: 창을 닫으면 사라지는 로그인(세션 쿠키)을 14일짜리로 바꿔 저장
async function keepLogins() {
  for (const name of ['persist:kakao', 'persist:naver']) {
    const ses = session.fromPartition(name);
    try {
      const list = await ses.cookies.get({});
      const until = Math.floor(Date.now() / 1000) + 14 * 86400;
      for (const c of list) {
        if (!c.session || !/kakao\.com|naver\.com/.test(c.domain || '')) continue;
        const host = (c.domain || '').replace(/^\./, '');
        try {
          await ses.cookies.set({ url: (c.secure ? 'https://' : 'http://') + host + (c.path || '/'), name: c.name, value: c.value,
            domain: c.domain, path: c.path, secure: c.secure, httpOnly: c.httpOnly, sameSite: c.sameSite, expirationDate: until });
        } catch (_) {}
      }
      await ses.cookies.flushStore();
    } catch (_) {}
  }
}
setInterval(keepLogins, 5 * 60 * 1000);
let savedBeforeQuit = false;
app.on('before-quit', (e) => {
  quitting = true;
  if (savedBeforeQuit) return;
  e.preventDefault();
  Promise.race([keepLogins(), new Promise((r) => setTimeout(r, 4000))]).then(() => { savedBeforeQuit = true; app.quit(); });
});

// ── 자동 업데이트: 다운로드 폴더에 "문의함-업데이트-vX.json" 파일이 생기면 알아서 적용
const CUR_VER = global.MH_VERSION || require(path.join(app.getAppPath(), 'package.json')).version;
const newer = (a, b) => { const x = String(a).split('.').map(Number), y = String(b).split('.').map(Number);
  for (let i = 0; i < 3; i++) { if ((x[i] || 0) !== (y[i] || 0)) return (x[i] || 0) > (y[i] || 0); } return false; };
const NEED = ['main-app.js', 'index.html', 'popup.html', 'preload-host.js', 'preload-guest.js'];
let asking = false; const skipped = new Set();
function findUpdates() {
  let dl; try { dl = app.getPath('downloads'); } catch (_) { return; }
  if (process.env.MH_DEV) console.log('SCAN', dl);
  let names = []; try { names = fs.readdirSync(dl); } catch (_) { return; }
  for (const f of names) {
    if (!/^(문의함-업데이트|munuiham-update).*\.json$/i.test(f)) continue;
    const full = path.join(dl, f);
    if (skipped.has(full) || asking) continue;
    let pkg; try { pkg = JSON.parse(fs.readFileSync(full, 'utf8')); } catch (_) { continue; }   // 아직 다운로드 중
    if (pkg.app !== 'munuiham' || !pkg.version || !pkg.files || !NEED.every((n) => typeof pkg.files[n] === 'string')) continue;
    if (!newer(pkg.version, CUR_VER)) { try { fs.unlinkSync(full); } catch (_) {} continue; }
    asking = true;
    if (win) showWin();
    (process.env.MH_AUTO_ACCEPT ? Promise.resolve({ response: 0 }) : dialog.showMessageBox(win, {
      type: 'info', title: '문의함 업데이트', buttons: ['지금 업데이트', '나중에'], defaultId: 0, cancelId: 1,
      message: `새 버전(v${pkg.version})이 준비됐어요.`,
      detail: (pkg.notes ? pkg.notes + '\n\n' : '') + '누르면 몇 초 안에 다시 켜져요. 로그인은 그대로 유지돼요.',
    })).then(({ response }) => {
      asking = false;
      if (response !== 0) { skipped.add(full); return; }
      try {
        const base = path.join(app.getPath('userData'), 'ui');
        const dir = path.join(base, pkg.version);
        fs.mkdirSync(dir, { recursive: true });
        for (const [n, c] of Object.entries(pkg.files)) {
          if (n.includes('/') || n.includes('\\') || n.includes('..')) continue;
          fs.writeFileSync(path.join(dir, n), c, 'utf8');
        }
        fs.writeFileSync(path.join(base, 'current.json'), JSON.stringify({ version: pkg.version }));
        try { fs.unlinkSync(full); } catch (_) {}
        quitting = true; app.relaunch(); app.quit();   // 급하게 끄지 않고 로그인 정보 저장 후 종료
      } catch (e) {
        dialog.showErrorBox('업데이트 실패', '업데이트를 적용하지 못했어요: ' + e.message);
      }
    });
    return;
  }
}
// ── 인터넷 자동 업데이트: GitHub(kd-messenger-update)의 latest.json을 1시간마다 확인
const ONLINE_UPDATE_URL = 'https://raw.githubusercontent.com/koreadata240707-glitch/kd-messenger-update/main/latest.json';
const skippedOnline = new Set();
async function checkOnlineUpdate() {
  if (asking) return;
  try {
    const res = await fetch(ONLINE_UPDATE_URL + '?t=' + Date.now(), { cache: 'no-store' });
    if (!res.ok) return;
    const pkg = await res.json();
    if (pkg.app !== 'munuiham' || !pkg.version || !pkg.files || !NEED.every((n) => typeof pkg.files[n] === 'string')) return;
    if (!newer(pkg.version, CUR_VER) || skippedOnline.has(pkg.version)) return;
    asking = true;
    if (win) showWin();
    const { response } = await dialog.showMessageBox(win, {
      type: 'info', title: 'KD통합메신저 업데이트', buttons: ['지금 업데이트', '나중에'], defaultId: 0, cancelId: 1,
      message: `새 버전(v${pkg.version})이 나왔어요.`,
      detail: (pkg.notes ? pkg.notes + '\n\n' : '') + '누르면 몇 초 안에 다시 켜져요. 로그인은 그대로 유지돼요.',
    });
    asking = false;
    if (response !== 0) { skippedOnline.add(pkg.version); return; }
    const base = path.join(app.getPath('userData'), 'ui');
    const dir = path.join(base, pkg.version);
    fs.mkdirSync(dir, { recursive: true });
    for (const [n, c] of Object.entries(pkg.files)) {
      if (n.includes('/') || n.includes('\\') || n.includes('..')) continue;
      fs.writeFileSync(path.join(dir, n), c, 'utf8');
    }
    fs.writeFileSync(path.join(base, 'current.json'), JSON.stringify({ version: pkg.version }));
    quitting = true; app.relaunch(); app.quit();
  } catch (_) { asking = false; }
}
app.whenReady().then(() => {
  setTimeout(checkOnlineUpdate, 20000);                 // 켜고 20초 뒤 한 번
  setInterval(checkOnlineUpdate, 60 * 60 * 1000);       // 그다음 1시간마다
  setTimeout(findUpdates, 3000);
  setInterval(findUpdates, 10000);
  try { fs.watch(app.getPath('downloads'), () => setTimeout(findUpdates, 1500)); } catch (_) {}
});
ipcMain.handle('version', () => CUR_VER);
ipcMain.handle('hash', (_, t) => require('crypto').createHash('sha256').update('munuiham:' + String(t)).digest('hex'));
ipcMain.on('copy', (_, text) => require('electron').clipboard.writeText(String(text || '')));

// ── 관리자: 개발 자료 내보내기 (지금 실행 중인 버전 전체 + 인수인계 문서를 zip으로 바탕화면에)
function crc32(buf) {
  let c, crc = 0xFFFFFFFF;
  for (let n = 0; n < buf.length; n++) {
    c = (crc ^ buf[n]) & 0xFF;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xEDB88320 ^ (c >>> 1) : c >>> 1;
    crc = (crc >>> 8) ^ c;
  }
  return (crc ^ 0xFFFFFFFF) >>> 0;
}
function makeZip(entries) {   // entries: [{ name, data: Buffer }], 압축 없이 저장(store)
  const locals = [], centrals = []; let offset = 0;
  for (const e of entries) {
    const name = Buffer.from(e.name, 'utf8'), crc = crc32(e.data), size = e.data.length;
    const lh = Buffer.alloc(30); lh.writeUInt32LE(0x04034b50, 0); lh.writeUInt16LE(20, 4); lh.writeUInt16LE(0x0800, 6); lh.writeUInt16LE(0, 8);
    lh.writeUInt32LE(0, 10); lh.writeUInt32LE(crc, 14); lh.writeUInt32LE(size, 18); lh.writeUInt32LE(size, 22); lh.writeUInt16LE(name.length, 26); lh.writeUInt16LE(0, 28);
    locals.push(lh, name, e.data);
    const ch = Buffer.alloc(46); ch.writeUInt32LE(0x02014b50, 0); ch.writeUInt16LE(20, 4); ch.writeUInt16LE(20, 6); ch.writeUInt16LE(0x0800, 8); ch.writeUInt16LE(0, 10);
    ch.writeUInt32LE(0, 12); ch.writeUInt32LE(crc, 16); ch.writeUInt32LE(size, 20); ch.writeUInt32LE(size, 24); ch.writeUInt16LE(name.length, 28);
    ch.writeUInt32LE(0, 30); ch.writeUInt32LE(0, 34); ch.writeUInt32LE(0, 38); ch.writeUInt32LE(offset, 42);
    centrals.push(ch, name);
    offset += 30 + name.length + size;
  }
  const cd = Buffer.concat(centrals);
  const end = Buffer.alloc(22); end.writeUInt32LE(0x06054b50, 0); end.writeUInt16LE(entries.length, 8); end.writeUInt16LE(entries.length, 10);
  end.writeUInt32LE(cd.length, 12); end.writeUInt32LE(offset, 16);
  return Buffer.concat([...locals, cd, end]);
}
async function exportDevZip(reveal) {
  const read = (n) => { for (const d of [__dirname, app.getAppPath()]) { try { return fs.readFileSync(path.join(d, n)); } catch (_) {} } return null; };
  const entries = [];
  for (const n of ['HANDOFF.md', 'main.js', 'main-app.js', 'index.html', 'popup.html', 'preload-host.js', 'preload-guest.js', 'make-update.js', 'tray.png', 'build/icon.png']) {
    const b = read(n); if (b) entries.push({ name: '문의함-개발자료/' + n, data: b });
  }
  // package.json은 지금 실행 중인 버전 번호로
  try {
    const pkg = JSON.parse(String(read('package.json') || '{}')); pkg.version = CUR_VER;
    entries.push({ name: '문의함-개발자료/package.json', data: Buffer.from(JSON.stringify(pkg, null, 2)) });
  } catch (_) {}
  const out = path.join(app.getPath('desktop'), `문의함-개발자료-v${CUR_VER}.zip`);
  fs.mkdirSync(path.dirname(out), { recursive: true });
  fs.writeFileSync(out, makeZip(entries));
  if (reveal) shell.showItemInFolder(out);
  return out;
}
ipcMain.handle('export-dev', () => exportDevZip(true));
// Claude로 보내기: 개발 자료 만들기 → (Claude 데스크톱 앱이 있으면) 파일이 첨부된 채로 열기 / (없으면) 웹 Claude + 폴더 열기
