      const seen = new Set(), words = [];
      const ALL = []; const walk = (r) => r.querySelectorAll('*').forEach((e) => { ALL.push(e); if (e.shadowRoot) walk(e.shadowRoot); }); walk(document);
      times.push(`제목:${document.title.slice(0, 30)} 글자수:${(document.body && document.body.innerText || '').length} 요소:${ALL.length} 그림자:${ALL.filter((e) => e.shadowRoot).length}`);
      ALL.forEach((el) => {
        if (words.length >= 30 || el.children.length) return;
        const t = (el.textContent || '').trim(); if (!t || t.length > 30 || seen.has(t)) return;
        const r = el.getBoundingClientRect(); if (!r.width || r.top < 0 || r.top > 1500) return;
        seen.add(t); const c = el.closest('a,button,[role=button]'); words.push(`${t}(${Math.round(r.top)}${c ? ',' + c.tagName[0] : getComputedStyle(el).cursor === 'pointer' ? ',P' : ''})`);
      });
      times.push('화면글자 ' + words.join(' '));
    }
    ipcRenderer.sendToHost('signal', { kind: 'diag', fid: FID, href: location.href.slice(0, 120), iframes, times, rows: rows.size, sample });
  } catch (e) { ipcRenderer.sendToHost('signal', { kind: 'diag', fid: FID, href: location.href, iframes: [], times: ['오류 ' + e.message], rows: 0, sample: [] }); }
});
ipcRenderer.on('open-chat', (_, name) => {
  const row = rows.get(name);
  if (row && document.contains(row)) {
    const target = row.querySelector('a') || row;
    target.scrollIntoView({ block: 'center' });
    target.click();
  }
});
window.addEventListener('pointerdown', () => { lastActAt = Date.now(); }, true);
window.addEventListener('keydown', () => { lastActAt = Date.now(); }, true);
// 직원이 입력창에 쓴 글 기억 (보낸 글이 목록 미리보기에 떠도 새 문의로 착각하지 않게)
let lastKeyAt = 0; const recentTyped = [];
const isBox = (t) => t && (t.tagName === 'TEXTAREA' || t.tagName === 'INPUT' || t.isContentEditable);
const valOf = (t) => String(t.value !== undefined ? t.value : t.innerText || '').trim();
const remember = (v) => { v = String(v || '').trim().split('\n')[0].slice(0, 60); if (v) { recentTyped.push(v); if (recentTyped.length > 8) recentTyped.shift(); } };
window.addEventListener('keydown', (e) => {
  const t = e.target; if (!isBox(t)) return;
  lastKeyAt = Date.now();
  if (e.key === 'Enter' && !e.shiftKey) remember(valOf(t));      // 엔터로 보낸 글
  else setTimeout(() => { t._mhLast = valOf(t); }, 0);
}, true);
window.addEventListener('input', (e) => {
  const t = e.target; if (!isBox(t)) return;
  if (!valOf(t) && t._mhLast) { remember(t._mhLast); t._mhLast = ''; }   // 전송 버튼으로 보내서 입력창이 비워진 경우
  else t._mhLast = valOf(t);
}, true);
window.addEventListener('click', () => {   // 전송 버튼 누르는 순간
  const t = document.activeElement; if (isBox(t) && valOf(t)) remember(valOf(t));
  document.querySelectorAll('textarea').forEach((x) => { if (x._mhLast) setTimeout(() => { if (!valOf(x)) { remember(x._mhLast); x._mhLast = ''; } }, 300); });
}, true);
// 페이지가 바뀌면 처음부터 다시 기준 잡기
let lastHref = location.href;

let last = -1;
setInterval(() => {
  try {
    if (location.href !== lastHref) { lastHref = location.href; prevSig = null; lastRows = -1; }
    scanChats();
  } catch (e) {}
  try {
    const n = rowUnread !== null ? rowUnread : countUnread();
    if (n !== last || Date.now() - lastCountAt > 5000) { last = n; lastCountAt = Date.now(); ipcRenderer.sendToHost('signal', { kind: 'count', count: n, fid: FID }); }
  } catch (e) {}
}, 3000);

// 3) 사람이 이 화면에서 클릭/입력하면 "봤다"는 신호를 보냅니다.
let lastAct = 0;
function activity() {
  const now = Date.now();
  if (now - lastAct < 1500) return; lastAct = now;
  ipcRenderer.sendToHost('signal', { kind: 'activity' });
}
window.addEventListener('pointerdown', activity, true);
window.addEventListener('keydown', activity, true);
window.addEventListener('wheel', activity, { capture: true, passive: true });

// ── 사이트가 띄우는 홍보/안내 창 자동으로 닫기 ("일주일간 보지 않기" 같은 문구가 있는 창만)
const SKIP_RE = /^(다시\s?보지\s?않기|일주일간?\s?보지\s?않기|7일간\s?보지\s?않기|오늘\s?하루\s?(동안\s?)?(보지\s?않기|열지\s?않기)|오늘\s?그만\s?보기|그만\s?보기)$/;
function closePromos() {
  const all = []; const walk = (r) => r.querySelectorAll('*').forEach((e) => { all.push(e); if (e.shadowRoot) walk(e.shadowRoot); }); walk(document);
  const vis = (e) => { const r = e.getBoundingClientRect(); return r.width > 0 && r.height > 0; };
  for (const el of all) {
    if (el.children.length > 1 || !vis(el)) continue;
    const t = (el.textContent || '').trim();
    if (!t || t.length > 20 || !SKIP_RE.test(t)) continue;
    // 그 문구가 들어 있는 떠 있는 창(layer) 찾기
    let layer = el;
    for (let i = 0; i < 12 && layer.parentElement; i++) {
      layer = layer.parentElement;
      const cs = getComputedStyle(layer);
      if ((cs.position === 'fixed' || cs.position === 'absolute') && layer.getBoundingClientRect().width > 250) break;
    }
    if (layer._mhClosed) continue;
    layer._mhClosed = true;
    try { (el.closest('label,button,a') || el).click(); } catch (_) {}            // 보지 않기 체크
    setTimeout(() => {
      const btns = [...layer.querySelectorAll('button,a,[role=button]')].filter(vis);
      const close = btns.find((b) => /닫기|close/i.test((b.getAttribute('aria-label') || '') + ' ' + (b.textContent || '').trim() + ' ' + (b.className || '')) && !SKIP_RE.test((b.textContent || '').trim()));
      if (close) close.click();
    }, 300);
  }
}
setInterval(() => { try { closePromos(); } catch (_) {} }, 3000);

// ── 카카오: 채팅 화면 왼쪽의 회색 메뉴 칸("채팅 설정 / 채팅방 메뉴 / 자동응답…")을 숨겨서 대화 목록이 가려지지 않게
function hideKakaoSubmenu() {
  if (!/business\.kakao\.com$/.test(location.host) || !/\/chats/.test(location.pathname)) return;
  const all = []; const walk = (r) => r.querySelectorAll('*').forEach((e) => { all.push(e); if (e.shadowRoot) walk(e.shadowRoot); }); walk(document);
  const mark = all.find((e) => !e.children.length && /^채팅방\s?메뉴$/.test((e.textContent || '').trim()) && e.getBoundingClientRect().width > 0);
  if (!mark) return;
  // "채팅" 제목까지 들어 있는 가장 바깥 메뉴 칸을 찾아서 통째로 숨김 (안쪽만 숨기면 빈 칸이 남아 목록을 가림)
  let p = mark, best = null;
  for (let i = 0; i < 14; i++) {
    const up = p.parentElement || (p.getRootNode && p.getRootNode().host);   // 숨은 영역 경계도 넘어서
    if (!up) break;
    p = up;
    const r = p.getBoundingClientRect();
    if (r.width >= 160 && r.width <= 360 && r.height >= 300 && /자동응답/.test(p.textContent || '')) best = p;   // 조건 맞는 것 중 가장 바깥 것
    else if (best && r.width > 360) break;
  }
  if (best) best.style.setProperty('display', 'none', 'important');
}
setInterval(() => { try { hideKakaoSubmenu(); } catch (_) {} }, 2000);

